import{transicionarEstado}from"./state-manager.min.js";import{STATE,ERROR_TYPE,ERROR_TYPES_FATALES}from"./constants.min.js";export function crearErrorRecovery(deps){var uiState=deps.uiState;var mostrarEstadoError=deps.mostrarEstadoError;var pintarEsqueleto=deps.pintarEsqueleto;var cargarCatalogo=deps.cargarCatalogo;return{procesar:function(error,tipoError,contexto){var detalles={tipo:tipoError,mensaje:error&&error.message?error.message:String(error),contexto:contexto,timestamp:Date.now()};console.error("[Error] "+tipoError+":",detalles);uiState.lastErrorState=detalles;if(ERROR_TYPES_FATALES.indexOf(tipoError)!==-1){mostrarEstadoError(tipoError,detalles);transicionarEstado(STATE.ERROR,tipoError)}return detalles},recuperarDeCarguaCatalogo:function(){if(uiState.lastErrorState&&uiState.lastErrorState.tipo===ERROR_TYPE.CATALOG_FETCH){if(window.AmbientEngine)window.AmbientEngine.reintentar();transicionarEstado(STATE.RECOVERING,"reintentando_catalogo");pintarEsqueleto();cargarCatalogo()}},registrarParaDebug:function(error,tipo){try{var debug=JSON.parse(localStorage.getItem("uruspot_debug_errors")||"[]");debug.push({tipo:tipo,mensaje:error&&error.message?error.message:String(error),stack:error&&error.stack?error.stack.substring(0,200):"",timestamp:(new Date).toISOString()});if(debug.length>10)debug.shift();localStorage.setItem("uruspot_debug_errors",JSON.stringify(debug))}catch(e){}}}}